use sqlx::any::{AnyPoolOptions, install_default_drivers};
use sqlx::AnyPool;

async fn open(url: &str) -> Result<AnyPool, sqlx::Error> {
    let pool = AnyPoolOptions::new()
        .max_connections(5)
        .connect(url)
        .await?;
    install_default_drivers();
    sqlx::query("SELECT 1").execute(&pool).await?;
    Ok(pool)
}

